(function () {
  'use strict';
  const pWin = window.parent || window;
  const pDoc = pWin.document || document;
  const STYLE_ID = 'xiaoye-shared-notebook-skin';
  const CSS = "/* Xiaoye shared notebook UI: safe direct-render skin */
.xiaoye-scope {
  --xy-ink: #2e3142;
  --xy-muted: #6f7485;
  --xy-paper: rgba(255, 252, 243, 0.94);
  --xy-line: rgba(130, 112, 96, 0.24);
  --xy-blue: #7ea8c6;
  --xy-peach: #f0aa8d;
  --xy-cream: #fff7df;
  --xy-page-bg:
    linear-gradient(135deg, rgba(255,255,255,0.94), rgba(255,247,223,0.82)),
    repeating-linear-gradient(0deg, transparent 0 27px, rgba(126,168,198,0.11) 28px);
  color: var(--xy-ink);
  font-family: "Noto Serif SC", "Microsoft YaHei", serif;
}
.xiaoye-card {
  position: relative;
  overflow: hidden;
  margin: 14px 0;
  border: 1px solid var(--xy-line);
  border-radius: 16px;
  background: var(--xy-page-bg);
  box-shadow: 0 12px 30px rgba(52, 62, 78, 0.14);
}
.xiaoye-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 8px;
  background: linear-gradient(180deg, var(--xy-blue), var(--xy-peach));
  opacity: 0.78;
}
.xy-status-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: center;
  padding: 12px 18px 10px 24px;
  border-bottom: 1px dashed rgba(130,112,96,0.26);
  background: rgba(255,255,255,0.34);
}
.xy-kicker {
  color: var(--xy-muted);
  font-size: 0.78em;
  letter-spacing: 0;
  text-transform: uppercase;
}
.xy-phase {
  color: #49677c;
  font-weight: 800;
}
.xy-meta {
  color: var(--xy-muted);
}
.xy-maintext {
  display: block;
  padding: 20px 24px 10px 28px;
  line-height: 1.9;
  white-space: pre-wrap;
}
.xy-status-board {
  margin: 8px 18px 18px 24px;
  border: 1px solid rgba(126,168,198,0.28);
  border-radius: 14px;
  background: rgba(255,255,255,0.45);
  overflow: hidden;
}
.xy-status-board summary {
  cursor: pointer;
  list-style: none;
  padding: 12px 14px;
  color: #4f6f86;
  font-weight: 800;
  border-bottom: 1px dashed rgba(130,112,96,0.22);
}
.xy-status-board summary::-webkit-details-marker {
  display: none;
}
.xy-status-inner {
  padding: 14px;
}
.xy-dual-panel {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}
.xy-panel {
  min-width: 0;
  padding: 12px;
  border: 1px solid rgba(130,112,96,0.18);
  border-radius: 12px;
  background: rgba(255,255,255,0.45);
}
.xy-name {
  margin-bottom: 8px;
  font-weight: 900;
}
.xy-stat-row {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  margin: 7px 0;
}
.xy-stat-label {
  color: var(--xy-muted);
  font-size: 0.88em;
}
.xy-meter {
  height: 8px;
  border-radius: 999px;
  background: rgba(126,168,198,0.16);
  overflow: hidden;
}
.xy-meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--xy-blue), var(--xy-peach));
}
.xy-small-note {
  color: #4f5364;
  line-height: 1.65;
  word-break: break-word;
}
.xy-letter {
  margin-top: 12px;
  padding: 11px 12px;
  border-left: 3px solid var(--xy-peach);
  border-radius: 10px;
  background: rgba(255,255,255,0.48);
  line-height: 1.75;
}
.xy-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}
.xy-tags span {
  padding: 3px 8px;
  border: 1px solid rgba(126,168,198,0.28);
  border-radius: 999px;
  background: rgba(126,168,198,0.13);
  color: #49677c;
  font-size: 0.86em;
}
@media (max-width: 640px) {
  .xy-status-strip,
  .xy-maintext,
  .xy-status-board {
    margin-left: 12px;
    margin-right: 12px;
    padding-left: 14px;
    padding-right: 14px;
  }
  .xy-dual-panel {
    grid-template-columns: 1fr;
  }
}";
  if (pDoc.getElementById(STYLE_ID)) return;
  const style = pDoc.createElement('style');
  style.id = STYLE_ID;
  style.textContent = CSS;
  pDoc.head.appendChild(style);
})();
